CREATE TABLE public.marketing_subscribers (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),email text not null,name text,subscribed boolean not null default true,consented_at timestamptz,unsubscribed_at timestamptz,source text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,email));
ALTER TABLE public.marketing_subscribers ENABLE ROW LEVEL SECURITY;
CREATE POLICY marketing_subscribers_org_access ON public.marketing_subscribers FOR ALL TO authenticated USING(public.is_admin(auth.uid()) OR exists(select 1 from public.organization_members m where m.organization_id=marketing_subscribers.organization_id and m.user_id=auth.uid() and m.papel::text in('admin','manager'))) WITH CHECK(public.is_admin(auth.uid()) OR exists(select 1 from public.organization_members m where m.organization_id=marketing_subscribers.organization_id and m.user_id=auth.uid() and m.papel::text in('admin','manager')));
CREATE TABLE public.marketing_segments (id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),name text not null,criteria jsonb not null default '{}'::jsonb,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
ALTER TABLE public.marketing_segments ENABLE ROW LEVEL SECURITY;
CREATE POLICY marketing_segments_org_access ON public.marketing_segments FOR ALL TO authenticated USING(public.is_admin(auth.uid()) OR exists(select 1 from public.organization_members m where m.organization_id=marketing_segments.organization_id and m.user_id=auth.uid() and m.papel::text in('admin','manager'))) WITH CHECK(public.is_admin(auth.uid()) OR exists(select 1 from public.organization_members m where m.organization_id=marketing_segments.organization_id and m.user_id=auth.uid() and m.papel::text in('admin','manager')));
CREATE OR REPLACE FUNCTION public.unsubscribe_marketing(p_organization_id uuid,p_email text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ begin insert into public.marketing_subscribers(organization_id,email,subscribed,unsubscribed_at) values(p_organization_id,lower(btrim(p_email)),false,now()) on conflict(organization_id,email) do update set subscribed=false,unsubscribed_at=now(); end $$;
REVOKE ALL ON FUNCTION public.unsubscribe_marketing(uuid,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.unsubscribe_marketing(uuid,text) TO anon,authenticated;

